"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import { useId, useState } from "react";

import { RefreshIcon, SparklesIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";

import { percentChange, sum } from "../lib/plot";
import { BlockFrame } from "../parts/block-frame";
import { Delta } from "../parts/delta";
import {
  DRIVERS,
  FOLLOW_UPS,
  LAST_WEEK,
  REASON,
  THIS_WEEK,
} from "./ai-insight-card/data";
import { DriverList } from "./ai-insight-card/driver-list";
import { InsightChart } from "./ai-insight-card/insight-chart";
import { StopIcon } from "./icons";
import { useTicker } from "./lib/use-ticker";
import { countAllWords, countWords, revealParts, takeWords } from "./lib/words";
import { StreamingText } from "./parts/streaming-text";

// Critically damped, so the panel opens fast and lands without a bounce.
const OPEN: Transition = {
  type: "spring",
  stiffness: 380,
  damping: 39,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };
const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

const PARTS = [REASON, ...DRIVERS.map((driver) => driver.title)];
const TOTAL_WORDS = countAllWords(PARTS);
// The longest follow-up sets the reserved height of the follow-up reply.
const LONGEST_FOLLOW_UP = FOLLOW_UPS.reduce(
  (longest, item) =>
    item.answer.length > longest.length ? item.answer : longest,
  "",
);

/**
 * A figure that explains itself. Explain streams a short reason, then three
 * ranked drivers, and each driver's numbered mark lights on the chart as it
 * is read. The panel reserves its full height, so the card never jumps.
 */
export function AiInsightCard({ className }: { className?: string }) {
  const reduceMotion = useReducedMotion();
  const [open, setOpen] = useState(false);
  const [hovered, setHovered] = useState<string | null>(null);
  const [followUp, setFollowUp] = useState<number | null>(null);
  const titleId = useId();
  const panelId = useId();

  // Two words a tick, about 25 words a second.
  const stream = useTicker(Math.ceil(TOTAL_WORDS / 2), 80);
  const shownParts = revealParts(PARTS, stream.tick * 2);
  const litMarks = shownParts.slice(1).filter(Boolean).length;
  const followText =
    followUp === null ? "" : (FOLLOW_UPS[followUp]?.answer ?? "");
  const followStream = useTicker(
    Math.ceil(countWords(LONGEST_FOLLOW_UP) / 2),
    80,
  );

  const now = sum(THIS_WEEK);
  const change = percentChange(sum(LAST_WEEK), now);

  const explain = () => {
    if (stream.running) {
      stream.stop();
      return;
    }
    if (open) {
      setOpen(false);
      setFollowUp(null);
      followStream.reset();
      return;
    }
    setOpen(true);
    stream.start();
  };

  const ask = (position: number) => {
    setFollowUp(position);
    followStream.start();
  };

  const status = stream.running
    ? "Explaining"
    : stream.done
      ? "Explanation ready"
      : open
        ? "Explanation stopped"
        : "";

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div className="flex flex-col gap-4 p-5">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <h2
              id={titleId}
              className="text-sm font-medium text-muted-foreground"
            >
              Booked visits this week
            </h2>
            <p className="mt-1 flex flex-wrap items-baseline gap-x-2 text-3xl font-semibold tracking-tight">
              <NumberTicker value={now} format={WHOLE} />
              <Delta value={change} className="text-sm" />
              <span className="text-xs font-normal text-muted-foreground">
                on last week
              </span>
            </p>
          </div>
          <Button
            variant={open && !stream.running ? "outline" : "default"}
            size="sm"
            aria-expanded={open}
            aria-controls={panelId}
            onClick={explain}
          >
            {stream.running ? (
              <StopIcon aria-hidden="true" />
            ) : (
              <SparklesIcon aria-hidden="true" className="size-4" />
            )}
            {stream.running ? "Stop" : open ? "Hide" : "Explain"}
          </Button>
        </div>

        <InsightChart litMarks={litMarks} showMarks={open} />
        <ul
          aria-label="Chart key"
          className="flex gap-4 text-xs text-muted-foreground"
        >
          <li className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              className="h-0.5 w-3 rounded-full bg-chart-1"
            />
            This week
          </li>
          <li className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              className="w-3 border-t border-dashed border-muted-foreground"
            />
            Last week
          </li>
        </ul>
      </div>

      <p role="status" className="sr-only">
        {status}
      </p>

      <AnimatePresence initial={false}>
        {open ? (
          <motion.div
            id={panelId}
            key="panel"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={reduceMotion ? INSTANT : OPEN}
            className="overflow-hidden"
          >
            <div
              aria-busy={stream.running}
              className="flex flex-col gap-4 border-t border-border p-5"
            >
              <div className="flex gap-2.5 text-sm leading-relaxed">
                {/* A box one text line tall centres the icon on the first line, with no nudge. */}
                <span className="flex h-5 shrink-0 items-center">
                  <SparklesIcon
                    aria-hidden="true"
                    className="size-4 shrink-0 text-chart-4"
                  />
                </span>
                <StreamingText
                  full={REASON}
                  shown={shownParts[0] ?? ""}
                  streaming={stream.running && shownParts[0] !== REASON}
                />
              </div>
              <div className="flex flex-col gap-2">
                <h3 className="px-2 text-xs font-medium text-muted-foreground">
                  What moved it
                </h3>
                <DriverList
                  drivers={DRIVERS}
                  shownTitles={shownParts.slice(1)}
                  hovered={hovered}
                  onHover={setHovered}
                />
              </div>
              <div className="flex flex-col gap-3">
                <div className="flex flex-wrap items-center gap-2">
                  {FOLLOW_UPS.map((item, position) => (
                    <Button
                      key={item.label}
                      variant={followUp === position ? "secondary" : "outline"}
                      size="sm"
                      aria-pressed={followUp === position}
                      disabled={!stream.done}
                      onClick={() => ask(position)}
                    >
                      {item.label}
                    </Button>
                  ))}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => stream.start()}
                    disabled={stream.running}
                    className="ml-auto"
                  >
                    <RefreshIcon aria-hidden="true" className="size-4" />
                    Retry
                  </Button>
                </div>
                <div
                  aria-live="polite"
                  className="text-sm text-muted-foreground"
                >
                  {followUp === null ? (
                    <p className="invisible" aria-hidden="true">
                      {LONGEST_FOLLOW_UP}
                    </p>
                  ) : (
                    <StreamingText
                      full={LONGEST_FOLLOW_UP}
                      shown={takeWords(followText, followStream.tick * 2)}
                      streaming={
                        followStream.running &&
                        takeWords(followText, followStream.tick * 2) !==
                          followText
                      }
                    />
                  )}
                </div>
              </div>
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

