export function DriverList({
  drivers,
  shownTitles,
  hovered,
  onHover,
}: DriverListProps) {
  const largest = Math.max(...drivers.map((driver) => Math.abs(driver.visits)));
  return (
    <ol className="flex flex-col gap-1" onPointerLeave={() => onHover(null)}>
      {drivers.map((driver, position) => {
        const shown = shownTitles[position] ?? "";
        const complete = shown === driver.title;
        const faded = hovered !== null && hovered !== driver.id;
        return (
          <li
            key={driver.id}
            onPointerEnter={() => onHover(driver.id)}
            className={cn(
              "relative isolate grid grid-cols-[1.25rem_1fr_auto] items-center gap-x-3 gap-y-1 rounded-lg px-2 py-2 motion-safe:transition-opacity motion-safe:duration-200",
              faded ? "opacity-45" : "opacity-100",
