          >
            <span
              aria-hidden="true"
              className={cn(
                "absolute inset-0 -z-10 rounded-lg",
                hovered === driver.id ? "bg-muted" : undefined,
              )}
            />
            <span
              aria-hidden="true"
              className={cn(
                "flex size-5 items-center justify-center rounded-full text-xs font-semibold motion-safe:transition-colors",
                shown
                  ? cn(DOT[driver.hue], "text-primary-foreground")
                  : "bg-muted text-muted-foreground",
              )}
            >
              {position + 1}
            </span>
            <span className="min-w-0">
              <span className="block min-h-5 truncate text-sm font-medium">
                {shown || (
                  <span
                    aria-hidden="true"
                    className="inline-block h-3 w-40 max-w-full rounded-full bg-muted"
                  />
                )}
              </span>
              <span
                className={cn(
                  "block truncate text-xs text-muted-foreground motion-safe:transition-opacity",
                  complete ? "opacity-100" : "opacity-0",
                )}
              >
                {driver.detail}
              </span>
            </span>
            <span
              className={cn(
                "text-right text-sm font-medium tabular-nums motion-safe:transition-opacity",
                complete ? "opacity-100" : "opacity-0",
                driver.visits < 0
                  ? "text-marketing-orange-ink"
                  : "text-marketing-green-ink",
              )}
            >
              {driver.visits < 0 ? "-" : "+"}
              {formatWhole(Math.abs(driver.visits))}
              <span className="sr-only"> visits</span>
            </span>
            <span
              aria-hidden="true"
              className="col-start-2 col-end-4 h-1.5 overflow-hidden rounded-full bg-muted"
            >
              <span
                className={cn(
                  "block h-full w-(--w) rounded-full motion-safe:transition-all motion-safe:duration-500",
                  BAR[driver.hue],
                )}
                style={
                  // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                  {
                    "--w": complete
                      ? `${(Math.abs(driver.visits) / largest) * 100}%`
                      : "0%",
                  } as VarStyle
                }
              />
            </span>
          </li>
        );
      })}
    </ol>
  );
}

